def transform(grid):
    n = len(grid)

    # Cells strictly left of the row's diagonal follow the repeating base sequence.
    known = [(c, grid[r][c]) for r in range(n) for c in range(min(r, n))
             if grid[r][c] != 0]

    period = None
    seq = None
    for p in range(1, 10):
        groups = [[] for _ in range(p)]
        for c, value in known:
            groups[c % p].append(value)
        if all(not g or len(set(g)) == 1 for g in groups):
            period = p
            seq = [g[0] if g else None for g in groups]
            break

    if period is None:
        period = 9
        groups = [[] for _ in range(period)]
        for c, value in known:
            groups[c % period].append(value)
        seq = [max(g, key=g.count) if g else 1 for g in groups]

    # Fill any missing sequence entries from the observed periodic values.
    for i in range(period):
        if seq[i] is None:
            seq[i] = next((grid[r][c] for r in range(n)
                           for c in range(min(r, n))
                           if c % period == i and grid[r][c] != 0), 1)

    return [[seq[(c - (1 if c >= r else 0)) % period]
             for c in range(n)] for r in range(n)]
